\frac{m}{n} = \frac{m}{n}, n \neq 0
\frac{m_1}{n_1} \cdot \frac{m_2}{n_2} = \frac{m_1 \cdot m_2}{n_1 \cdot n_2}
\frac{m_1}{n_1} = \frac{m_2}{n_2} \iff m_1 \cdot n_2 = m_2 \cdot n_1
\frac{m_1}{n_1} + \frac{m_2}{n_2} = \frac{m_1 n_2 + m_2 n_1}{n_1 n_2}
\frac{m_1}{n_1} + \frac{m_2}{n_2} \in \mathbb{Q}
\frac{m_1}{n_1} < \frac{m_2}{n_2} \iff m_1 \cdot n_2 < m_2 \cdot n_1

\frac{m_1}{n_1} \cdot \frac{m_2}{n_2} = \frac{m_1 m_2}{n_1 n_2}
\frac{m_1}{n_1} + \frac{m_2}{n_2} = \frac{m_1 n_2 + m_2 n_1}{n_1 n_2}
\frac{m_1}{n_1} + \frac{m_2}{n_2} \in \mathbb{Q}
\Longleftrightarrow m_1 n_2 = m_2 n_1
\frac{m_1}{n_1} < \frac{m_2}{n_2}
\Longleftrightarrow
m_1 n_2 < m_2 n_1
